{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE snitch_db.maplemonk.SALES_ANALYSIS_SHIRTS as WITH sku_base AS ( SELECT DISTINCT CASE WHEN UPPER(TRIM(sku)) LIKE \'SN%\' OR UPPER(TRIM(sku)) LIKE \'BP%\' THEN UPPER(TRIM(sku)) WHEN UPPER(TRIM(sku)) LIKE \'MP%\' THEN UPPER(TRIM(REGEXP_SUBSTR(sku::STRING, \'^[^-]+-[^-]+-[^-]+\'))) ELSE CASE WHEN UPPER(TRIM(sku)) LIKE \'%-%\' THEN UPPER(TRIM(REGEXP_SUBSTR(sku::STRING, \'^[^-]+-[^-]+\'))) ELSE UPPER(TRIM(sku_group)) END END AS sku_group FROM SNITCH_DB.MAPLEMONK.logic_purchase_order ), Meta_base as ( select sku_group, category, meta1 , meta2, meta3 from snitch_db.maplemonk.meta_mapping_cogs_sku ), live_date_base AS ( SELECT DISTINCT CASE WHEN UPPER(TRIM(sku_group)) LIKE \'SN%\' OR UPPER(TRIM(sku_group)) LIKE \'BP%\' THEN UPPER(TRIM(sku_group)) WHEN UPPER(TRIM(sku_group)) LIKE \'MP%\' THEN UPPER(TRIM(REGEXP_SUBSTR(sku_group::STRING, \'^[^-]+-[^-]+-[^-]+\'))) ELSE CASE WHEN UPPER(TRIM(sku_group)) LIKE \'%-%\' THEN UPPER(TRIM(REGEXP_SUBSTR(sku_group::STRING, \'^[^-]+-[^-]+\'))) ELSE UPPER(TRIM(sku_group)) END END AS sku_group, live_date FROM snitch_db.maplemonk.category_journey ), SLEEVE_TYPE AS ( SELECT CASE WHEN UPPER(TRIM(sku_group)) LIKE \'SN%\' OR UPPER(TRIM(sku_group)) LIKE \'BP%\' THEN UPPER(TRIM(sku_group)) WHEN UPPER(TRIM(sku_group)) LIKE \'MP%\' THEN UPPER(TRIM(REGEXP_SUBSTR(sku_group::STRING, \'^[^-]+-[^-]+-[^-]+\'))) ELSE CASE WHEN UPPER(TRIM(sku_group)) LIKE \'%-%\' THEN UPPER(TRIM(REGEXP_SUBSTR(sku_group::STRING, \'^[^-]+-[^-]+\'))) ELSE UPPER(TRIM(sku_group)) END END AS sku_group, SLEEVE_TYPE AS SLEEVES FROM SNITCH_DB.MAPLEMONK.METAFIELDS_DATA ), sales_first_order AS ( SELECT CASE WHEN UPPER(TRIM(sku_group)) LIKE \'SN%\' OR UPPER(TRIM(sku_group)) LIKE \'BP%\' THEN UPPER(TRIM(sku_group)) WHEN UPPER(TRIM(sku_group)) LIKE \'MP%\' THEN UPPER(TRIM(REGEXP_SUBSTR(sku_group::STRING, \'^[^-]+-[^-]+-[^-]+\'))) ELSE CASE WHEN UPPER(TRIM(sku_group)) LIKE \'%-%\' THEN UPPER(TRIM(REGEXP_SUBSTR(sku_group::STRING, \'^[^-]+-[^-]+\'))) ELSE UPPER(TRIM(sku_group)) END END AS sku_group, MIN(date) AS first_order_date FROM snitch_db.maplemonk.horizontal_sales_categories GROUP BY 1 ), inward_date AS ( SELECT CASE WHEN UPPER(TRIM(\"Item Type skuCode\")) LIKE \'SN%\' THEN UPPER(TRIM(\"Item Type skuCode\")) WHEN UPPER(TRIM(\"Item Type skuCode\")) LIKE \'BP%\' THEN UPPER(TRIM(\"Item Type skuCode\")) WHEN UPPER(TRIM(\"Item Type skuCode\")) LIKE \'MP%\' THEN UPPER(TRIM(REGEXP_SUBSTR(\"Item Type skuCode\"::STRING, \'^[^-]+-[^-]+-[^-]+\'))) ELSE UPPER(TRIM(COALESCE( REGEXP_SUBSTR(\"Item Type skuCode\"::STRING, \'^[^-]+-[^-]+\', 1, 1), \"Item Type skuCode\"::STRING ))) END AS sku_group, MIN(putaway_completed_date) AS inward_date, SUM(CASE WHEN \"Warehouse Name\" IN (\'SAPL-WH2\',\'SAPL-NORTH-TAURU\') THEN putaway_completed_quantity ELSE 0 END) AS inwarded FROM snitch_db.maplemonk.putaway_tracking GROUP BY 1 ), base_final AS ( SELECT p.sku_group, q.live_date, h.first_order_date, i.inward_date, i.inwarded, mb.category, mb.meta1, mb.meta2, mb.meta3, K.SLEEVES, CASE WHEN q.live_date > h.first_order_date THEN i.inward_date ELSE q.live_date END AS sales_start_date FROM sku_base p LEFT JOIN live_date_base q ON p.sku_group = q.sku_group LEFT JOIN sales_first_order h ON p.sku_group = h.sku_group LEFT JOIN inward_date i ON p.sku_group = i.sku_group left join meta_base mb on p.sku_group = mb.sku_group LEFT JOIN sleeve_type k on p.sku_group = k.sku_group ), sales_after_cutoff AS ( SELECT b.sku_group, SUM(s.gross_sales) AS sales_value, SUM(s.gross_quantity) AS sales_qty, MAX(s.date) AS last_sales_date FROM base_final b LEFT JOIN snitch_db.maplemonk.horizontal_sales_categories s ON ( CASE WHEN UPPER(TRIM(s.sku_group)) LIKE \'SN%\' OR UPPER(TRIM(s.sku_group)) LIKE \'BP%\' THEN UPPER(TRIM(s.sku_group)) WHEN UPPER(TRIM(s.sku_group)) LIKE \'MP%\' THEN UPPER(TRIM(REGEXP_SUBSTR(s.sku_group::STRING, \'^[^-]+-[^-]+-[^-]+\'))) ELSE CASE WHEN UPPER(TRIM(s.sku_group)) LIKE \'%-%\' THEN UPPER(TRIM(REGEXP_SUBSTR(s.sku_group::STRING, \'^[^-]+-[^-]+\'))) ELSE UPPER(TRIM(s.sku_group)) END END ) = b.sku_group AND s.date > b.sales_start_date GROUP BY 1 ), sales_daily AS ( SELECT b.sku_group, s.date AS sales_date, SUM(s.gross_quantity) AS daily_sales_qty FROM base_final b JOIN snitch_db.maplemonk.horizontal_sales_categories s ON ( CASE WHEN UPPER(TRIM(s.sku_group)) LIKE \'SN%\' OR UPPER(TRIM(s.sku_group)) LIKE \'BP%\' THEN UPPER(TRIM(s.sku_group)) WHEN UPPER(TRIM(s.sku_group)) LIKE \'MP%\' THEN UPPER(TRIM(REGEXP_SUBSTR(s.sku_group::STRING, \'^[^-]+-[^-]+-[^-]+\'))) ELSE CASE WHEN UPPER(TRIM(s.sku_group)) LIKE \'%-%\' THEN UPPER(TRIM(REGEXP_SUBSTR(s.sku_group::STRING, \'^[^-]+-[^-]+\'))) ELSE UPPER(TRIM(s.sku_group)) END END ) = b.sku_group AND s.date > b.sales_start_date GROUP BY 1, 2 ), sales_windowed AS ( SELECT b.sku_group, SUM(CASE WHEN s.date > b.sales_start_date AND s.date <= DATEADD(day, 30, b.sales_start_date) THEN s.gross_quantity ELSE 0 END) AS sales_qty_30_days, SUM(CASE WHEN s.date > b.sales_start_date AND s.date <= DATEADD(day, 60, b.sales_start_date) THEN s.gross_quantity ELSE 0 END) AS sales_qty_60_days, SUM(CASE WHEN s.date > b.sales_start_date AND s.date <= DATEADD(day, 90, b.sales_start_date) THEN s.gross_quantity ELSE 0 END) AS sales_qty_90_days FROM base_final b LEFT JOIN snitch_db.maplemonk.horizontal_sales_categories s ON ( CASE WHEN UPPER(TRIM(s.sku_group)) LIKE \'SN%\' OR UPPER(TRIM(s.sku_group)) LIKE \'BP%\' THEN UPPER(TRIM(s.sku_group)) WHEN UPPER(TRIM(s.sku_group)) LIKE \'MP%\' THEN UPPER(TRIM(REGEXP_SUBSTR(s.sku_group::STRING, \'^[^-]+-[^-]+-[^-]+\'))) ELSE CASE WHEN UPPER(TRIM(s.sku_group)) LIKE \'%-%\' THEN UPPER(TRIM(REGEXP_SUBSTR(s.sku_group::STRING, \'^[^-]+-[^-]+\'))) ELSE UPPER(TRIM(s.sku_group)) END END ) = b.sku_group GROUP BY 1 ), sales_cumulative AS ( SELECT d.sku_group, d.sales_date, d.daily_sales_qty, SUM(d.daily_sales_qty) OVER ( PARTITION BY d.sku_group ORDER BY d.sales_date ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW ) AS cumulative_sales_qty FROM sales_daily d ), sales_milestones AS ( SELECT b.sku_group, MIN(CASE WHEN c.cumulative_sales_qty >= b.inwarded * 0.30 THEN c.sales_date END) AS sold_30_pct_date, MIN(CASE WHEN c.cumulative_sales_qty >= b.inwarded * 0.60 THEN c.sales_date END) AS sold_60_pct_date, MIN(CASE WHEN c.cumulative_sales_qty >= b.inwarded * 0.90 THEN c.sales_date END) AS sold_90_pct_date FROM base_final b LEFT JOIN sales_cumulative c ON b.sku_group = c.sku_group GROUP BY 1 ), final AS ( SELECT b.sku_group, b.category, b.meta1, b.meta2, b.meta3, b.sleeves, b.live_date, b.first_order_date, b.inward_date, b.sales_start_date, s.last_sales_date, b.inwarded, COALESCE(s.sales_value, 0) AS sales_value, COALESCE(s.sales_qty, 0) AS sales_qty, COALESCE(w.sales_qty_30_days, 0) AS sales_qty_30_days, COALESCE(w.sales_qty_60_days, 0) AS sales_qty_60_days, COALESCE(w.sales_qty_90_days, 0) AS sales_qty_90_days, m.sold_30_pct_date, m.sold_60_pct_date, m.sold_90_pct_date FROM base_final b LEFT JOIN sales_after_cutoff s ON b.sku_group = s.sku_group LEFT JOIN sales_milestones m ON b.sku_group = m.sku_group LEFT JOIN sales_windowed w ON b.sku_group = w.sku_group ) SELECT DISTINCT *, DATEDIFF(day, sales_start_date, LAST_DAY(\'2025-12-01\'::DATE)) AS days_on_sale, ROUND( COALESCE( sales_qty / NULLIF( DATEDIFF(day, sales_start_date, LAST_DAY(\'2025-12-01\'::DATE)), 0 ), 0 ) ,2) AS ROS, ROUND( COALESCE( (sales_qty / NULLIF(inwarded, 0)) * 100 ,0) ,2) AS STR, ROUND(COALESCE(sales_qty_30_days, 0),2) AS sales_qty_30_days, ROUND(COALESCE(sales_qty_60_days, 0),2) AS sales_qty_60_days, ROUND(COALESCE(sales_qty_90_days, 0),2) AS sales_qty_90_days, DATEDIFF(day, sales_start_date, sold_30_pct_date) AS days_to_30_pct_sold, DATEDIFF(day, sales_start_date, sold_60_pct_date) AS days_to_60_pct_sold, DATEDIFF(day, sales_start_date, sold_90_pct_date) AS days_to_90_pct_sold, ROUND( COALESCE(sales_qty_30_days / NULLIF(30, 0), 0) ,2) AS ros_30_days, ROUND( COALESCE(sales_qty_60_days / NULLIF(60, 0), 0) ,2) AS ros_60_days, ROUND( COALESCE(sales_qty_90_days / NULLIF(90, 0), 0) ,2) AS ros_90_days FROM final WHERE live_date >= \'2025-09-01\' AND live_date < \'2025-12-15\' and category ilike \'shirts\';",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from snitch_db.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            